package net.minecraft.nbt; public class CompoundTag extends Tag {private final java.util.Map<String,Object> fields=new java.util.HashMap<>();public ListTag getList(String k,int ignored){return (ListTag)fields.getOrDefault(k,new ListTag());}public boolean hasUUID(String k){return fields.get(k) instanceof java.util.UUID;}public java.util.UUID getUUID(String k){return (java.util.UUID)fields.get(k);}public String getString(String k){return (String)fields.get(k);}public long getLong(String k){return (Long)fields.get(k);}public void putUUID(String k,java.util.UUID v){fields.put(k,v);}public void putString(String k,String v){fields.put(k,v);}public void putLong(String k,long v){fields.put(k,v);}public void put(String k,ListTag v){fields.put(k,v);}}
